<?php
use App\Models\{Customer,Equipment,Site};use App\Support\CurrentCompany;use Illuminate\Support\Facades\Gate;use Illuminate\Validation\Rule;use Livewire\Attributes\{Title,Url};use Livewire\Component;
new #[Title('Update Customer')] class extends Component {public Customer $customer;#[Url]public string $tab='details';public string $name='';public ?string $trading_name=null;public string $account_number='';public ?int $home_site_id=null;public array $siteIds=[];public array $equipmentIds=[];public function mount(CurrentCompany $current,Customer $customer):void{abort_unless($customer->company_id===$current->id(auth()->user()),404);$this->customer=$customer;$this->name=$customer->name;$this->trading_name=$customer->trading_name;$this->account_number=$customer->account_number;$this->home_site_id=$customer->home_site_id;$this->siteIds=$customer->sites()->pluck('sites.id')->all();$this->equipmentIds=$customer->equipment()->pluck('equipment.id')->all();}public function save():void{Gate::authorize('crm.customer.update');$data=$this->validate(['name'=>['required','max:255'],'trading_name'=>['nullable','max:255'],'account_number'=>['required','max:255',Rule::unique('customers')->ignore($this->customer->id)],'home_site_id'=>['nullable','exists:sites,id'],'siteIds'=>['array'],'siteIds.*'=>['exists:sites,id'],'equipmentIds'=>['array'],'equipmentIds.*'=>[Rule::exists('equipment','id')->where('company_id',$this->customer->company_id)]]);$this->customer->update(collect($data)->only(['name','trading_name','account_number','home_site_id'])->all());$sites=$data['siteIds'];if($data['home_site_id'])$sites[]=$data['home_site_id'];$this->customer->sites()->sync(array_unique($sites));$this->customer->equipment()->sync($data['equipmentIds']);Flux::toast(text:'Customer updated',variant:'success');}public function with():array{return ['sites'=>Site::orderBy('name')->get(),'equipment'=>Equipment::where('company_id',$this->customer->company_id)->with('equipmentModel.make')->orderBy('stock_number')->get(),'movements'=>$this->customer->movements()->latest()->limit(50)->get()];}};?>
<section class="w-full p-6"><div class="flex justify-between"><flux:heading size="xl">{{ $customer->name }}</flux:heading><flux:button :href="route('crm.customers.index')">Back</flux:button></div><x-pages::shared.layout contentclass="max-w-5xl"><div class="mb-5 flex gap-2 border-b pb-3">@foreach(['details'=>'Basic Details','addresses'=>'Addresses','equipment'=>'Equipment','movements'=>'Movements'] as $key=>$label)<flux:button type="button" :variant="$tab===$key?'primary':'ghost'" wire:click="$set('tab','{{ $key }}')">{{ $label }}</flux:button>@endforeach</div><form wire:submit="save" class="space-y-5">@if($tab==='details')<flux:card class="grid gap-5 md:grid-cols-2"><flux:input wire:model="name" label="Name"/><flux:input wire:model="trading_name" label="Trading name"/><flux:input wire:model="account_number" label="Account number"/></flux:card>@elseif($tab==='addresses')<div class="grid gap-5 md:grid-cols-2"><flux:card><flux:select wire:model="home_site_id" variant="combobox" label="Head office"><flux:select.option value="">Not set</flux:select.option>@foreach($sites as $site)<flux:select.option :value="$site->id">{{ $site->name }} — {{ $site->formattedAddress() }}</flux:select.option>@endforeach</flux:select></flux:card><flux:card><flux:pillbox wire:model="siteIds" multiple searchable label="Depots">@foreach($sites as $site)<flux:pillbox.option :value="$site->id">{{ $site->name }} — {{ $site->postcode }}</flux:pillbox.option>@endforeach</flux:pillbox></flux:card></div>@elseif($tab==='equipment')<flux:card><flux:pillbox wire:model="equipmentIds" multiple searchable label="Assigned equipment">@foreach($equipment as $item)<flux:pillbox.option :value="$item->id">{{ $item->stock_number }} — {{ $item->equipmentModel->make->name }} {{ $item->equipmentModel->name }}</flux:pillbox.option>@endforeach</flux:pillbox></flux:card>@else<flux:table><flux:table.columns><flux:table.column>Reference</flux:table.column><flux:table.column>Status</flux:table.column><flux:table.column>Date</flux:table.column></flux:table.columns><flux:table.rows>@forelse($movements as $movement)<flux:table.row><flux:table.cell><a href="{{ route('operations.movements.update',$movement) }}">{{ $movement->reference }}</a></flux:table.cell><flux:table.cell>{{ $movement->status->label() }}</flux:table.cell><flux:table.cell>{{ $movement->planned_date?->format('d M Y')?:'—' }}</flux:table.cell></flux:table.row>@empty<flux:table.row><flux:table.cell colspan="3">No movements.</flux:table.cell></flux:table.row>@endforelse</flux:table.rows></flux:table>@endif @unless($tab==='movements')<div class="flex justify-end"><flux:button type="submit" variant="primary">Save changes</flux:button></div>@endunless</form></x-pages::shared.layout></section>
